/// untagged package.
pub fn changed_source_files_since_last_tag(
    packages: &[&Package],
    tags: &TagIndex,
    git: &GitAccess<'_>,
    ignore: &[&str],
) -> Result<BTreeMap<PackageId, Vec<PathBuf>>, GraphError> {
