    /// The direct child (`sh`) exits at once, but a backgrounded grandchild (`sleep 30`) keeps stderr open. The
    /// reader-thread wait is bounded, so the call returns promptly and reports the incomplete output as an error
    /// instead of an empty success.
    #[test]
    fn run_with_timeout_bounds_reader_join_when_descendant_holds_pipe_open() {
        let runner = CliCommandRunner;
        let start = Instant::now();
        let result = runner.run_with_timeout(
            "sh",
            &["-c", "sleep 30 >&2 & exit 0"],
            std::path::Path::new("."),
            Duration::from_secs(2),
        );
        let elapsed = start.elapsed();
        assert!(
            elapsed < Duration::from_secs(6),
            "run_with_timeout must not block on a descendant process holding \
             stdio pipes open; took {elapsed:?}, result: {result:?}"
        );
        assert!(
            matches!(result, Err(CommandError::Io { .. })),
            "a clean exit with output cut short by a lingering descendant must be an error, got: {result:?}"
        );
    }

    /// concurrently with `wait_with_output` draining stdout/stderr on this
    /// one -- proven here by completing well within a generous bound
    /// instead of hanging.
    #[test]
    fn run_with_stdin_does_not_deadlock_on_a_payload_larger_than_a_pipe_buffer() {
        let runner = CliCommandRunner;
        let payload = vec![b'x'; 4 * 1024 * 1024];
        let start = Instant::now();
        let out = runner.run_with_stdin("cat", &[], Path::new("."), &payload).unwrap();
        let elapsed = start.elapsed();

        assert!(out.success());
        assert_eq!(out.stdout.len(), payload.len());
        assert!(
            elapsed < Duration::from_secs(10),
            "run_with_stdin must not deadlock on a large payload; took {elapsed:?}"
        );
    }

